	public class FlameZoneHurtState : ZoneHurtState
	{
		public FlameZoneHurtState(string newName, FSM newFSM, ZoneEnemy newEnt)
			: base(newName, newFSM, newEnt)
		{
		}

		public override void OnEnter()
		{
			base.OnEnter();
			PoolManager.GetPoolItem<ParticleEffect>("MetalDebrisEmitter").Emit(2, parent.transform.position + Vector3.up * 0.5f);
		}

		public override void PlayHurtAudio()
		{
			string audioID = "Squeak0";
			Vector2? soundOrigin = parent.transform.position;
			float overridePitch = Random.Range(0.5f, 0.6f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
			audioID = "MetalHit";
			soundOrigin = parent.transform.position;
			overridePitch = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
		}
	}

	public class FlameZoneDeadState : ZoneDeadState
	{
		public FlameZoneDeadState(string newName, FSM newFSM, ZoneEnemy newEnt)
			: base(newName, newFSM, newEnt)
		{
		}

		public override void OnEnter()
		{
			base.OnEnter();
			Vector2 vector = parent.transform.position + Vector3.up * 0.5f;
			PoolManager.GetPoolItem<ParticleEffect>("SmokeEmitter").Emit(12, vector);
			PoolManager.GetPoolItem<ParticleEffect>("MetalDebrisEmitter").Emit(10, vector);
			FireBurst poolItem = PoolManager.GetPoolItem<FireBurst>();
			int? particleCount = 3;
			Vector3? position = vector;
			Vector3? localEulerAngles = Globals.GetRotationVector(Vector3.up);
			poolItem.EmitSingle(particleCount, position, null, localEulerAngles);
		}

		public override void PlayDeadAudio()
		{
			base.PlayDeadAudio();
			string audioID = "MetalBreak";
			Vector2? soundOrigin = parent.transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		}
	}

	public override void InitFSM()
	{
		base.InitFSM();
		fsm.AddState(new FlameZoneAttackState("Attack", fsm, this));
		fsm.AddState(new EnemyFallState("Fall", fsm, this));
		fsm.ReplaceState(new FlameZoneHurtState("Hurt", fsm, this));
		fsm.ReplaceState(new FlameZoneDeadState("Dead", fsm, this));
	}

