	public class FrostArcherArrowShowerState : SkillState
	{
		private int arrowCount = 5;

		private float arrowInterval = 0.2f;

		private int arrowStopwatchID;

		private float arrowFallTime;

		private bool arrowsFired;

		private float randomOffset = 0.75f;

		private static GameObject iceArrowMedPrefab;

		private ArrowShower currentAS;

		public new FrostArcher parent;

		public FrostArcherArrowShowerState(string newName, FSM newFSM, FrostArcher newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			parent = newEnt;
			requireLineOfSight = false;
			iceArrowMedPrefab = ChaosBundle.Get("Assets/Prefabs/Effects/IceArrowMed.prefab");
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			parent.anim.Play("ArrowShowerWindup");
			Vector3 rotationVector = Globals.GetRotationVector(Vector2.up);
			if (!parent.isFacingRight)
			{
				rotationVector.z *= -1f;
			}
			rotationVector.z += 90f;
			parent.bowArm.localEulerAngles = rotationVector;
			arrowFallTime = StdWindupTime * 1.5f;
			arrowStopwatchID = ChaosStopwatch.Begin(arrowInterval, useInterval: true, arrowInterval, arrowCount);
			arrowsFired = false;
		}

		public override void Update()
		{
			if (!arrowsFired)
			{
				switch (ChaosStopwatch.CheckInterval(arrowStopwatchID))
				{
				case StopwatchState.Running:
					break;
				case StopwatchState.Ready:
					if (parent.UpdateTargetInfo() == null)
					{
						arrowsFired = true;
						break;
					}
					FireArrow(parent.closestTargetInfo.position);
					parent.anim.Play("ArrowShowerRelease", -1, 0f);
					SoundManager.PlayAudioWithDistance("FrostArcherIceArrowShower", parent.transform.position);
					Object.Instantiate(iceArrowMedPrefab, parent.arrowSpawn.position, Quaternion.identity);
					break;
				case StopwatchState.Done:
					arrowsFired = true;
					exitStopwatchID = ChaosStopwatch.Begin(exitTime);
					parent.anim.Play("Idle");
					DeactivatePowerUpEffect();
					break;
				}
			}
			else if (ChaosStopwatch.Check(exitStopwatchID))
			{
				ExitTransition();
			}
		}

		public void FireArrow(Vector2 targetPosition)
		{
			GameObject prefab = ArrowShower.Prefab;
			float radius = randomOffset;
			currentAS = ChaosInst<ArrowShower>(prefab, targetPosition.Randomize(1f, radius, 0f));
			currentAS.fallTime = arrowFallTime;
			currentAS.attackBox.SetAttackInfo(parent.skillCategory, skillID);
		}
	}

	public override void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new IdleState("Idle", fsm, this));
		fsm.AddState(new GoBackState("GoBack", fsm, this));
		fsm.AddState(new ChaseState("Chase", fsm, this));
		fsm.AddState(new EnemyDeadState("Dead", fsm, this));
		fsm.AddState(new EnemyHurtState("Hurt", fsm, this));
		fsm.AddState(new EnemyFallState("Fall", fsm, this));
		fsm.AddState(new DashState("Dash", fsm, this, 1, 10, 0f, 5f, 3f)
		{
			dashAway = true,
			dashOverPits = true,
			randomOffSet = 1f,
			castingAnimName = "Dash"
		});
		attackSkillID = "FrostArcherAttack";
		fsm.AddState(new FrostArcherAttackState("Attack", fsm, this));
		fsm.AddState(new FrostArcherArrowShowerState("FrostArcherArrowShower", fsm, this, 1, 5, 0f, attackRadius + 2f, 7f));
		fsm.AddState(new FrostArcherIceTrapState("FrostArcherIceTrap", fsm, this, 2, 7, 0f, attackRadius, 8f));
		fsm.ChangeState(fsm.defaultStateName);
	}
}

