		public IceShard CreateIceShard()
		{
			currentIS = base.CreateProjectile() as IceShard;
			currentIS.projectileLight.SetActive(value: false);
			currentIS.transform.SetParent(parent.arrowSpawn);
			currentIS.transform.localPosition = Vector3.right * (projectileCount - projectileCounter - 3) * 0.25f;
			projectilePositionDict[currentIS.transform.localPosition] = currentIS.transform;
			currentIS.attackWhileSpinning = false;
			currentIS.flashDuration = 0f;
			currentIS.Show();
			currentIS.playFormSound = false;
			return currentIS;
		}

		public override void HoldProjectile()
		{
			if (projectileList.Count > 0 && projectileList[0] != null)
			{
				parent.targetLine.transform.position = projectileList[0].transform.position;
			}
			foreach (KeyValuePair<Vector3, Transform> item in projectilePositionDict)
			{
				if (item.Value != null)
				{
					item.Value.localPosition = item.Key;
				}
			}
			foreach (IceShard projectile in projectileList)
			{
				if (projectile != null)
				{
					projectile.RefreshFlightTime();
				}
			}
		}

		public override void ReleaseProjectile()
		{
			currentIS = projectileList[projectileList.Count - 1];
			if (!(currentIS == null))
			{
				projectileList.Remove(currentIS);
				currentIS.transform.SetParent(null);
				currentIS.transform.localScale = Vector3.one;
				currentIS.PointIceShard(aimVector);
				currentIS.ReleaseIceShard(aimVector);
				currentIS.attackBox.knockbackOverwriteVector = aimVector;
				currentIS.moveSpeed = 40f;
				currentIS.flyTime = 0.4f;
				currentIS.InitTimers();
				SoundManager.PlayAudioWithDistance("FrostArcherIceArrow", parent.transform.position);
			}
		}

