		{
			base.OnEnter();
			projectileCounter = 0;
			chargeTime = 0.125f + StdWindupTime * 0.75f;
			projectileSpawnStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, chargeTime / (float)projectileCount, projectileCount);
		}

		public override void Update()
		{
			if (!projectileCreated)
			{
				parent.UpdateTargetInfo(parent.attackRadius * attackRangeModifier);
				if (parent.closestTargetInfo == null)
				{
					ExitTransition();
					return;
				}
				AimTowardsTarget();
				parent.anim.Play("AttackWindup", -1, (float)projectileCounter / (float)projectileCount);
				if (!parent.HandleExtraSkills(hasLOS: true, updateTarget: true, updateLOS: true))
				{
					switch (ChaosStopwatch.CheckInterval(projectileSpawnStopwatchID))
					{
					case StopwatchState.Ready:
						projectileList.Add(CreateIceShard());
						projectileCounter++;
						break;
					case StopwatchState.Done:
						projectileCreated = true;
						chargeDelayStopwatchID = ChaosStopwatch.Begin(chargeDelay);
						projectileReleaseStopwatchID = ChaosStopwatch.Begin(chargeDelay + projectileReleaseDelay, useInterval: true, projectileReleaseDelay, projectileCount);
						break;
