					if (!drawSoundPlayed && ChaosStopwatch.GetTimePercentage(chargeStopwatchID) > 0.25f)
					{
						drawSoundPlayed = true;
						SoundManager.PlayAudioWithDistance("ArcherAttackWindup", parent.transform.position);
					}
				}
			}
			else if (!projectileReleased)
			{
				if (!ChaosStopwatch.Check(chargeDelayStopwatchID))
				{
					AimTowardsTarget();
					return;
				}
				switch (ChaosStopwatch.CheckInterval(projectileReleaseStopwatchID))
				{
				case StopwatchState.Running:
					break;
				case StopwatchState.Ready:
					parent.targetLine.IsVisible(status: false);
