	{
		public new Laser parent;

		private AudioSource beamAudio;

		private int atkStopwatchID;

		private bool atkEnabled;

		private bool targetCompleted;

		public ShootState(string newStateName, FSM parentFSM, Laser parentEntity)
			: base(newStateName, parentFSM, parentEntity)
		{
			parent = parentEntity;
		}

		public override void OnEnter()
		{
			parent.SetTargetLineVars();
			PoolManager.GetPoolItem<ParticleEffect>("AirWaveShockwave").Emit(1, parent.transform.position, localEulerAngles: Globals.GetRotationVector((parent.transform.position - parent.targetVector).normalized), overrides: ParticleEffectOverrides.StartColorAlpha0p25);
			PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(4, parent.transform.position);
			SoundManager.PlayAudioWithDistance("ChaosBeamStart", parent.transform.position);
			CameraController.ShakeCamera(1f, ignoreShakeCount: true);
			parent.attack.SetAttackInfo(parent.skillCategory, parent.skillID, parent.skillLevel, parent.skillIsUltimate);
			InitShootEffects();
			if (parent.timeTilMaxRange != 0f)
			{
				parent.rangeStopwatchID = ChaosStopwatch.Begin(parent.timeTilMaxRange);
			}
			targetCompleted = false;
		}

		public override void FixedUpdate()
		{
			if (targetCompleted)
			{
				if (!atkEnabled)
				{
					atkEnabled = true;
					parent.attackCollider.gameObject.SetActive(value: true);
				}
				if (ChaosStopwatch.Check(atkStopwatchID))
				{
					atkStopwatchID = ChaosStopwatch.Begin(parent.hitCooldownTime);
					parent.attackCollider.gameObject.SetActive(value: false);
					atkEnabled = false;
				}
			}
		}

		public override void Update()
		{
			UpdateTargetLines();
			parent.attackCollider.offset = new Vector2(parent.targetLine0.range * 0.5f + parent.attackOriginOffset, 0f);
			parent.attackCollider.size = new Vector2(Mathf.Clamp(parent.targetLine0.range - parent.attackOriginOffset * 2f, parent.minAttackLen, 999f), parent.targetLine2.thickness * parent.atkVisualRatio);
			parent.attackTrans.localEulerAngles = new Vector3(0f, 0f, parent.targetLine0.transform.localEulerAngles.z + 90f);
			RandomizeShootThickness();
			UpdateShootEffects();
			if (beamAudio == null || !beamAudio.isPlaying)
			{
				beamAudio = SoundManager.PlayAudioWithDistance("ChaosBeamLoop", parent.transform.position);
			}
