	{
		musicEmitTimer = new ChaosQuickStopwatch(musicEmitTime);
		parent.anim.Play("DanceDown");
		EmoteEmitter emoteEmitter = parent.emoteEmitter;
		EmoteType emoteType = EmoteType.Hum;
		Vector3? position = parent.emoteTrans.position;
		emoteEmitter.Emit(emoteType, null, position, ParticleEffectOverrides.LayerOverlayDoodad, null, 0f, null, parent.emoteTrans);
