			fsm.ChangeState("MoveOn");
		}
		else if (!parent.inputDevice.GetButton("Skill2"))
		{
			fsm.ChangeState("Idle");
		}
		else if (emitCounter < emitCountMax && !musicEmitTimer.IsRunning)
		{
			emitCounter++;
			musicEmitTimer.IsRunning = true;
			PoolManager.GetPoolItem<ParticleEffect>("MusicNoteEmitter").Emit(1, parent.emoteTrans.position + Vector3.one * 0.75f, ParticleEffectOverrides.StartSpeed1p5);
