	public override void OnEnter()
	{
		base.OnEnter();
		castAnimPlayed = false;
		firstWaveSpawned = false;
		waveStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, waveDelay, waveCount);
		vulQueued = false;
		SoundManager.PlayAudioWithDistance("EnemyCast", parent.transform.position);
		parent.anim.Play("Charging", -1, 0f);
	}

	public override void ExecuteSkill()
	{
		if (firstWaveSpawned && !castAnimPlayed && !castAnimTimer.IsRunning)
		{
			parent.anim.Play("Cast", -1, 0f);
			castAnimPlayed = true;
			CameraController.ShakeCamera(0.3f);
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 20;
			float z = Globals.GetRotationVector(-targetVector).z;
			Vector3? emitPosition = parent.transform.position;
			poolItem.EmitDirBurst(particleCount, z, -1f, -1f, -1f, emitPosition);
		}
		else if (firstWaveSpawned && castAnimPlayed && parent.anim.AnimPlayed(0.4f))
		{
			parent.anim.Play("Charging", -1, 0f);
		}
		switch (ChaosStopwatch.CheckInterval(waveStopwatchID))
		{
		case StopwatchState.Ready:
			if (!FireMinions())
			{
				base.ExecuteSkill();
				break;
			}
			if (!firstWaveSpawned)
			{
				firstWaveSpawned = true;
			}
			castAnimTimer.IsRunning = true;
			castAnimPlayed = false;
			break;
		case StopwatchState.Done:
			if (castAnimPlayed && parent.anim.AnimPlayed())
			{
				base.ExecuteSkill();
			}
			break;
		}
	}

	private bool FireMinions()
	{
		currentMinionCount = parent.orbChList.Count;
		if (currentMinionCount == 0 || parent.UpdateTargetInfo() == null)
		{
			return false;
		}
		halfCount = (int)((float)currentMinionCount * 0.5f);
		UpdateTargetVector();
		middlePosition = (Vector2)parent.transform.position + targetVector;
		perpendVec = Globals.GetPerpendicular(targetVector) * 1.25f;
		linePosition = middlePosition - halfCount * perpendVec;
		for (int i = 0; i < currentMinionCount; i++)
		{
			currentOC = parent.orbChList[i] as OrbChargeFamiliar;
			if (!(currentOC == null))
			{
				CreatePortalEffect(currentOC);
				currentOC.fsm.ChangeState(currentOC.fsm.defaultStateName, allowSelfTransition: true);
				currentOC.QueueAttackState(targetVector, useDelay: true);
				currentOC.transform.position = Globals.GetLinecastVector(middlePosition, linePosition + perpendVec * i, ChaosCollisions.layerAllWall);
				currentOC.movement.EndMovement();
				CreatePortalEffect(currentOC);
			}
		}
		SoundManager.PlayWithDistAndSPR("ChaosFormLong", parent.transform.position);
		return true;
	}

	private void RecallMinions()
	{
		currentMinionCount = parent.orbChList.Count;
		middlePosition = parent.transform.position;
		for (int i = 0; i < currentMinionCount; i++)
		{
			currentOC = parent.orbChList[i] as OrbChargeFamiliar;
			if (!(currentOC == null))
			{
				CreatePortalEffect(currentOC);
				currentOC.fsm.ChangeState(currentOC.fsm.defaultStateName, allowSelfTransition: true);
				currentOC.transform.position = Globals.GetLinecastVector(middlePosition, middlePosition + Globals.GetCirclePositionVector(currentMinionCount, i) * 6f, ChaosCollisions.layerAllWall);
				currentOC.movement.EndMovement();
				CreatePortalEffect(currentOC);
			}
		}
		SoundManager.PlayWithDistAndSPR("ChaosFormLong", parent.transform.position);
	}

	public override void ExitTransition()
	{
		if (!vulQueued)
		{
			vulQueued = true;
			parent.AllowHurtState(status: true);
			vulStopwatchID = ChaosStopwatch.Begin(vulDuration);
			RecallMinions();
		}
		else if (ChaosStopwatch.Check(vulStopwatchID))
		{
			parent.AllowHurtState(status: false);
			base.ExitTransition();
		}
	}

	public void CreatePortalEffect(Enemy givenEnemy)
	{
		ChaosBurst.Spawn(givenEnemy.spriteRenderer.transform.position, 10);
	}
}

