using System;
using UnityEngine;

public class SwordThrowProjectile : Projectile
{
	private static GameObject prefab;

	[HideInInspector]
	public Transform parentTrans;

	[HideInInspector]
	public bool isEmpowered;

	private bool empoweredEffectStarted;

	private bool empoweredEffectFinished;

	public ChaosQuickStopwatch empoweredStopwatch = new ChaosQuickStopwatch(0.25f);

	private SwordThrowProjectile empoweredSTP;

	private static Color empShadowColor = new Color(0.6f, 0.6f, 0.6f, 0.8f);

	private static Color empActualColor = new Color(1f, 1f, 1f, 0.6f);

	private ChaosQuickStopwatch dustTimer;

	private float dustInterval = 0.1f;

	private ChaosQuickStopwatch arcStopwatch = new ChaosQuickStopwatch(0.25f);

	public bool useArc;

	public bool positiveArc;

	public float arcBias = 0.625f;

	private float arcLerpValue;

	private Vector2 initMoveVector;

	private Vector2 lerpExtVector;

	private float rotationalAngle;

	private Vector2 rightBound;

	private Vector2 leftBound;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/SwordThrow.prefab"));

	public override void Start()
	{
		base.Start();
		dustTimer = new ChaosQuickStopwatch(dustInterval);
		if (useArc)
		{
			InitArcVars();
		}
	}

	public override void Update()
	{
		if (CheckMaxLifeTime() || !ChaosStopwatch.Check(flyStopwatchID))
		{
			return;
		}
		if (parentObject == null || parentTrans == null)
		{
			ResetProjectile();
			return;
		}
		useArc = false;
		if (!dustTimer.IsRunning)
		{
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 20;
			float scale = 0.25f;
			Vector3? emitPosition = transform.position;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			dustTimer.IsRunning = true;
		}
		if (!boomerangReturning)
		{
			boomerangReturning = true;
			if (attackBox != null)
			{
				attackBox.gameObject.SetActive(value: false);
				attackBox.ChangeAttackInfoLevel(2);
			}
			UpdateCalculatedDamage(initDamageOverride: true);
		}
		else if (isEmpowered && !empoweredEffectFinished)
		{
			if (!empoweredEffectStarted)
			{
				moveVector = Vector2.zero;
				empoweredEffectStarted = true;
				empoweredStopwatch.IsRunning = true;
				empoweredSTP = Globals.ChaosInst<SwordThrowProjectile>(Prefab, transform.parent, transform.position);
				empoweredSTP.flyTime = 0f;
				empoweredSTP.parentObject = parentObject;
				empoweredSTP.parentEntity = parentEntity;
				empoweredSTP.parentTrans = parentTrans;
				empoweredSTP.boomerangReturning = true;
				UpdateCalculatedDamage(initDamageOverride: true);
				empoweredSTP.attackBox.SetAttackInfo(attackBox.atkInfo, 2);
				attackBox.ChangeAttackInfoLevel(3);
				empoweredSTP.projectileSpriteRenderer.color = empActualColor;
				projectileSpriteRenderer.color = empShadowColor;
			}
			else
			{
				empoweredEffectFinished = !empoweredStopwatch.IsRunning;
			}
		}
		else
		{
			if (attackBox != null)
			{
				attackBox.gameObject.SetActive(value: true);
			}
			if (boomerangReturning && Vector2.Distance(transform.position, parentTrans.position) < returningSnapDistance)
			{
				ResetProjectile();
			}
		}
	}

	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (!isEmpowered || !empoweredEffectStarted || empoweredEffectFinished)
		{
			if (useArc)
			{
				arcLerpValue = arcStopwatch.TimePercentage;
				lerpExtVector = arcBias * Vector2.Lerp(rightBound, leftBound, (!positiveArc) ? (1f - arcLerpValue) : arcLerpValue);
				moveVector = (initMoveVector + lerpExtVector).normalized;
			}
			else if (boomerangReturning && parentTrans != null)
			{
				moveVector = (parentTrans.position - transform.position).normalized;
			}
			attackBox.knockbackOverwriteVector = moveVector;
		}
	}

	private void InitArcVars()
	{
		initMoveVector = moveVector;
		arcStopwatch.SetDelay(flyTime, stopCurrent: false, autoStart: true);
		rotationalAngle = Vector3.Angle(Vector3.up, initMoveVector) * ((float)Math.PI / 180f) * ((!(initMoveVector.x > 0f)) ? 1f : (-1f));
		rightBound = new Vector2(Mathf.Cos(rotationalAngle), Mathf.Sin(rotationalAngle));
		rotationalAngle += (float)Math.PI;
		leftBound = new Vector2(Mathf.Cos(rotationalAngle), Mathf.Sin(rotationalAngle));
	}

	public override void ResetProjectile()
	{
		base.ResetProjectile();
		PoolManager.GetPoolItem<ParticleEffect>("WindTwirlEffect").Emit(1, transform.position, ParticleEffectOverrides.FlipX, new Vector3(0f, 0f, UnityEngine.Random.Range(-30f, 30f) + ((!Globals.RandBool) ? 180f : 0f)));
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 30;
		float scale = 0.05f;
		Vector3? emitPosition = transform.position;
		poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
	}

	public override void UpdateCalculatedDamage(bool initDamageOverride = false)
	{
		projectileCollisionModifier = ((!isEmpowered) ? 2 : 3);
		base.UpdateCalculatedDamage(initDamageOverride);
	}
}

