public class ThrownCoffinBlock : ThrownItem
{
	private static GameObject prefab;

	public Attack attack;

	public Collider2D attackCol;

	private ChaosQuickStopwatch attackStopwatch = new ChaosQuickStopwatch(0.125f);

	private bool attackEnabled;

	public int jumpCountMax;

	public float jumpInterval = 0.25f;

	public float jumpRange = 4f;

	public Vector2 jumpVector;

	private int jumpCounter;

	private int jumpStopwatchID = -1;

	private bool jumpQueued;

	public int paletteIndexOverride = -1;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/ThrownItems/ThrownCoffinBlock.prefab"));

	public override void Awake()
	{
		base.Awake();
		spriteTrans = transform.Find("ItemSprite");
	}

	public override void Start()
	{
		base.Start();
		if (paletteIndexOverride >= 0)
		{
			spriteRenderer.material.SetFloat("_PaletteIndex", paletteIndexOverride);
		}
	}

	public override void Update()
	{
		if (spriteRenderer != null)
		{
			spriteRenderer.sortingLayerName = ((!(spriteTrans.localPosition.y > 2f)) ? "Actor" : "OverlayDoodad");
		}
		if (jumpQueued && ChaosStopwatch.Check(jumpStopwatchID))
		{
			jumpQueued = false;
			targetPosition = (Vector2)transform.position + jumpVector * jumpRange;
			if (GetLineCastTargetPosition(transform.position, targetPosition) != targetPosition)
			{
				jumpCountMax = 0;
			}
			InitThrow();
		}
		else if (attackEnabled && !attackStopwatch.IsRunning)
		{
			attackEnabled = false;
			attackCol.enabled = false;
		}
	}

	public override void InitThrow()
	{
		base.InitThrow();
		destroyAfterLanding = true;
	}

	public override void OnLanding()
	{
		if (jumpCounter < jumpCountMax)
		{
			jumpCounter++;
			jumpStopwatchID = ChaosStopwatch.Begin(jumpInterval);
			jumpQueued = true;
			throwInitiated = false;
			throwComplete = false;
			destroyAfterLanding = false;
			destroyTime = 0.25f;
		}
		base.OnLanding();
		attackEnabled = true;
		attackCol.enabled = true;
		attackStopwatch.IsRunning = true;
		Vector2 vector = transform.position;
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 80;
		float scale = 1f;
		Vector3? emitPosition = vector;
		poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
		PoolManager.GetPoolItem<ParticleEffect>("FloorCraterSmall").Emit(1, vector);
		string audioID = "EarthExplosion";
		Vector2? soundOrigin = vector;
		scale = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, scale);
		CameraController.ShakeCamera();
	}

	private void OnDestroy()
	{
		PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle((paletteIndexOverride >= 0) ? RockDebrisType.Dark : RockDebrisType.Default, 5, transform.position + Vector3.up, RockDebrisEmitter.SmallCircleSlowExplosionOverride);
		PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle((paletteIndexOverride >= 0) ? RockDebrisType.Dark : RockDebrisType.Default, 3, transform.position + Vector3.up * 1.66f, RockDebrisEmitter.SmallCircleSlowExplosionOverride);
		PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle((paletteIndexOverride >= 0) ? RockDebrisType.Dark : RockDebrisType.Default, 2, transform.position + Vector3.left * 0.75f, RockDebrisEmitter.SmallCircleSlowExplosionOverride);
		PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle((paletteIndexOverride >= 0) ? RockDebrisType.Dark : RockDebrisType.Default, 2, transform.position + Vector3.right * 0.75f, RockDebrisEmitter.SmallCircleSlowExplosionOverride);
	}
}

